#!/usr/bin/env node
/**
 * Repository checks:  node tools/check.js          (all checks)
 *                     node tools/check.js min      (only: minified files are reproducible and up to date)
 *
 * Checks: structure, minified files, versions, license notices, absence of stray permissive-license files,
 * documentation links and demo registration, CSS syntax, workflows. Exit code 1 on any failure.
 */
import { existsSync, readFileSync, readdirSync, statSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { build, transform } from 'esbuild';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const at = (...p) => join(root, ...p);
const read = (p) => readFileSync(at(p), 'utf8');
const only = process.argv[2];
let failures = 0;
const ok = (name) => console.log(`  ok    ${name}`);
const fail = (name, detail) => { failures++; console.log(`  FAIL  ${name}${detail ? '\n        ' + [].concat(detail).join('\n        ') : ''}`); };
const check = (name, bad) => { const b = [].concat(bad).filter(Boolean); b.length ? fail(name, b) : ok(name); };

const walk = (dir, skip = ['node_modules', '.git', 'public']) => readdirSync(at(dir)).flatMap((n) => {
  if (skip.includes(n)) return [];
  const rel = join(dir, n);
  return statSync(at(rel)).isDirectory() ? walk(rel, skip) : [rel];
});
const tracked = () => readdirSync(root).filter((n) => !['node_modules', '.git', 'public', 'package-lock.json'].includes(n))
  .flatMap((n) => (statSync(at(n)).isDirectory() ? walk(n) : [n]))
  // generated by `npm run build` (documentation site), not part of the repository
  .filter((f) => !/^dist\/(index\.html|assets|examples|plugins|dist)(\/|$)/.test(f.replace(/\\/g, '/')));

/* ---- minified files are reproducible ---- */
async function checkMin() {
  const js = await build({ entryPoints: [at('src/abi7-grid.js')], write: false, outfile: 'x.min.js', format: 'esm', target: 'es2022', minify: true, sourcemap: 'external', legalComments: 'inline', bundle: false, logLevel: 'silent' });
  const css = await build({ entryPoints: [at('src/abi7-grid.css')], write: false, outfile: 'x.min.css', minify: true, legalComments: 'inline', bundle: false, logLevel: 'silent' });
  const text = (r, ext) => r.outputFiles.find((f) => f.path.endsWith(ext)).text;
  const same = (file, expected) => existsSync(at(file)) && read(file) === expected;
  const bad = [];
  if (!existsSync(at('dist/abi7-grid.min.js'))) bad.push('dist/abi7-grid.min.js is missing');
  else {
    // the .map file references the output name, so only the code itself is compared
    const strip = (s) => s.replace(/\n?\/\/# sourceMappingURL=.*\s*$/, '');
    if (strip(read('dist/abi7-grid.min.js')) !== strip(text(js, '.js'))) bad.push('dist/abi7-grid.min.js is out of date: run npm run build:lib');
  }
  if (!existsSync(at('dist/abi7-grid.min.js.map'))) bad.push('dist/abi7-grid.min.js.map is missing');
  if (!existsSync(at('dist/abi7-grid.min.css'))) bad.push('dist/abi7-grid.min.css is missing');
  else if (read('dist/abi7-grid.min.css').replace(/\s+$/, '') !== text(css, '.css').replace(/\s+$/, '')) bad.push('dist/abi7-grid.min.css is out of date: run npm run build:lib');
  if (!same('dist/abi7-grid.js', read('src/abi7-grid.js'))) bad.push('dist/abi7-grid.js differs from src/abi7-grid.js');
  if (!same('dist/abi7-grid.css', read('src/abi7-grid.css'))) bad.push('dist/abi7-grid.css differs from src/abi7-grid.css');
  check('minified files are reproducible and up to date', bad);
}

console.log('ABI7 Grid repository checks');
await checkMin();
if (only === 'min') process.exit(failures ? 1 : 0);

const pkg = JSON.parse(read('package.json'));

/* ---- structure ---- */
const required = ['README.md', 'LICENSE', 'CHANGELOG.md', 'CONTRIBUTING.md', 'CODE_OF_CONDUCT.md', 'SECURITY.md', 'package.json',
  'src/abi7-grid.js', 'src/abi7-grid.css', 'plugins/README.md', '.github/workflows/validate.yml', '.github/workflows/pages.yml',
  '.github/PULL_REQUEST_TEMPLATE.md', 'docs/publishing.md', 'tests/core.test.js',
  ...['LICENSE-COMMUNITY', 'LICENSE-COMMERCIAL-SINGLE-DEVELOPER', 'LICENSE-COMMERCIAL-UNLIMITED-DEVELOPERS', 'THIRD-PARTY-LICENSES', 'COPYRIGHT', 'TRADEMARK', 'LICENSE-FAQ'].map((n) => `licenses/${n}.md`)];
check('required files exist', required.filter((f) => !existsSync(at(f))).map((f) => 'missing: ' + f));
check('core is exactly one JS and one CSS file', [JSON.stringify(readdirSync(at('src')).filter((f) => /^abi7-grid\./.test(f)).sort()) === '["abi7-grid.css","abi7-grid.js"]' ? '' : 'src/ must contain exactly abi7-grid.js and abi7-grid.css']);
check('every plugin has source, README and package.json', readdirSync(at('plugins')).filter((d) => statSync(at('plugins', d)).isDirectory())
  .flatMap((d) => ['README.md', 'package.json'].filter((f) => !existsSync(at('plugins', d, f))).map((f) => `plugins/${d}/${f} missing`)
    .concat(readdirSync(at('plugins', d)).some((f) => f.endsWith('.js')) ? [] : [`plugins/${d} has no .js file`])));

/* ---- versions ---- */
const coreVersion = /export const VERSION = '([^']+)'/.exec(read('src/abi7-grid.js'))[1];
const headerVersion = /ABI7 Grid v([\d.]+)/.exec(read('src/abi7-grid.js'))[1];
check('versions are consistent', [
  coreVersion !== pkg.version && `VERSION in src (${coreVersion}) != package.json (${pkg.version})`,
  headerVersion !== pkg.version && `header comment (${headerVersion}) != package.json (${pkg.version})`,
  !new RegExp(`^## ${pkg.version.replace(/\./g, '\\.')}\\b`, 'm').test(read('CHANGELOG.md')) && `CHANGELOG.md has no section for ${pkg.version}`,
  !read('docs/app.js').includes(`v${pkg.version}`) && `docs/app.js does not show v${pkg.version}`
]);

/* ---- package.json ---- */
check('package.json fields', [
  ...['name', 'version', 'description', 'author', 'homepage', 'repository', 'bugs', 'keywords', 'license', 'main', 'browser', 'files'].filter((k) => !pkg[k]).map((k) => `missing field: ${k}`),
  !String(pkg.license).startsWith('SEE LICENSE IN licenses/') && 'license must be "SEE LICENSE IN licenses/…" (the Community License is not a standard SPDX license)',
  pkg.private === true && 'package.json is private: remove it before publishing (and do not publish before the legal review)',
  !/https:\/\/abi7\.com/.test(pkg.licenseNotice || '') && 'licenseNotice must point to https://abi7.com',
  !String(pkg.repository && pkg.repository.url).includes('abilogic/abi7-grid') && 'repository.url must be abilogic/abi7-grid'
]);
check('files listed in package.json "files" exist', (pkg.files || []).filter((f) => !f.includes('*') && !existsSync(at(f))).map((f) => 'missing: ' + f));

/* ---- no stray permissive license ---- */
const files = tracked();
const textFiles = files.filter((f) => /\.(md|js|css|html|json|yml|yaml|tsx|ts|txt|svg)$/.test(f) || /^LICENSE$/.test(f));
const forbidden = new RegExp(['\\b' + 'M' + 'IT\\b', 'Permission is hereby ' + 'granted, free of charge'].join('|'));
check('no stray permissive license text or identifier', textFiles.filter((f) => forbidden.test(read(f))).map((f) => 'found in ' + f));
check('no LICENSE file other than the Community notice', files.filter((f) => /(^|\/)(LICENSE|LICENCE|COPYING)(\.(txt|md))?$/.test(f.replace(/\\/g, '/')) && !/^licenses\//.test(f) && f !== 'LICENSE'));

/* ---- license notices ---- */
const withHeader = files.filter((f) => /^(src\/abi7-grid\.(js|css)|plugins\/.*\.(js|css))$/.test(f.replace(/\\/g, '/')));
check('license header in every library and plugin file', withHeader.filter((f) => { const h = read(f).slice(0, 700); return !(h.startsWith('/*!') && /Alexander Momot/.test(h) && /abi7\.com/.test(h)); }).map((f) => 'missing/short header: ' + f));
const phrases = {
  'README.md': ['Commercial use requires a paid license', 'ABI7 Grid Community is free for non-commercial use only', '$29', '$199', 'https://abi7.com', 'Alexander Momot', 'https://github.com/abilogic/abi7-grid'],
  'LICENSE': ['https://abi7.com', '$29', '$199', 'FREE FOR NON-COMMERCIAL USE ONLY'],
  'licenses/LICENSE-COMMUNITY.md': ['Non-Commercial Use', 'https://abi7.com', '$29', '$199', 'Alexander Momot'],
  'licenses/LICENSE-COMMERCIAL-SINGLE-DEVELOPER.md': ['$29', 'https://abi7.com'],
  'licenses/LICENSE-COMMERCIAL-UNLIMITED-DEVELOPERS.md': ['$199', 'https://abi7.com', 'Subsidiar'],
  'plugins/README.md': ['https://abi7.com'], 'CONTRIBUTING.md': ['https://abi7.com'], 'licenses/LICENSE-FAQ.md': ['https://abi7.com']
};
check('license notices and prices are present', Object.entries(phrases).flatMap(([f, ps]) => ps.filter((p) => !read(f).includes(p)).map((p) => `${f}: missing "${p}"`)));
const pages = readdirSync(at('docs/pages')).filter((f) => f.endsWith('.md')).map((f) => f.replace(/\.md$/, ''));
check('commercial-license notice is shown on every docs page', [/Get a commercial license at https:\/\/abi7\.com/.test(read('docs/app.js')) ? '' : 'docs/app.js must render the commercial-license notice']);

/* ---- documentation links and demos ---- */
const badLinks = [];
for (const p of pages) {
  const src = read(`docs/pages/${p}.md`);
  for (const m of src.matchAll(/\(#\/([\w-]+)(?:\/[^)]*)?\)/g)) if (!pages.includes(m[1])) badLinks.push(`docs/pages/${p}.md -> #/${m[1]}`);
  for (const m of src.matchAll(/^:::markdown (\S+)$/gm)) if (!existsSync(at(m[1]))) badLinks.push(`docs/pages/${p}.md -> ${m[1]}`);
  for (const m of src.matchAll(/^:::file (\S+)$/gm)) if (!existsSync(at(m[1]))) badLinks.push(`docs/pages/${p}.md -> ${m[1]}`);
}
const navIds = [...read('docs/app.js').matchAll(/\['([\w-]+)', '/g)].map((m) => m[1]);
for (const id of navIds) if (!pages.includes(id)) badLinks.push(`navigation entry without page: ${id}`);
for (const p of pages) if (!navIds.includes(p)) badLinks.push(`page not in navigation: ${p}`);
for (const f of ['README.md', 'CONTRIBUTING.md', 'plugins/README.md', ...files.filter((x) => /^licenses\/.*\.md$/.test(x.replace(/\\/g, '/')))]) {
  for (const m of read(f).matchAll(/\]\((?!https?:|#|mailto:)([^)\s#]+)(?:#[^)]*)?\)/g)) if (!existsSync(resolve(dirname(at(f)), m[1]))) badLinks.push(`${f} -> ${m[1]}`);
}
check('documentation links resolve', badLinks);

const viewer = read('docs/viewer.js');
const registered = new Set([...viewer.matchAll(/^\s+'?([\w-]+)'?: (?:ex\(|\{)/gm)].map((m) => m[1]));
const exampleDirs = readdirSync(at('examples')).filter((d) => d !== 'shared');
const usedDemos = new Set(pages.flatMap((p) => [...read(`docs/pages/${p}.md`).matchAll(/^:::demo ([\w-]+)$/gm)].map((m) => m[1])));
check('every example is runnable, registered and shown in the docs', [
  ...exampleDirs.filter((d) => !existsSync(at('examples', d, 'index.html')) || !existsSync(at('examples', d, 'demo.js'))).map((d) => `examples/${d}: index.html or demo.js missing`),
  ...exampleDirs.filter((d) => !registered.has(d)).map((d) => `examples/${d}: not registered in docs/viewer.js`),
  ...exampleDirs.filter((d) => !usedDemos.has(d)).map((d) => `examples/${d}: no :::demo on any page`),
  ...[...usedDemos].filter((d) => !exampleDirs.includes(d)).map((d) => `:::demo ${d}: no such example`)
]);

/* ---- CSS syntax ---- */
const cssBad = [];
for (const f of files.filter((x) => x.endsWith('.css') && !x.startsWith('docs/'))) {
  try { const r = await transform(read(f), { loader: 'css', logLevel: 'silent' }); if (r.warnings.length) cssBad.push(`${f}: ${r.warnings[0].text}`); } catch (e) { cssBad.push(`${f}: ${e.message.split('\n')[0]}`); }
}
check('CSS parses without warnings', cssBad);

/* ---- workflows ---- */
const wf = read('.github/workflows/pages.yml');
check('GitHub Pages workflow builds and deploys', [!/actions\/deploy-pages/.test(wf) && 'pages.yml must use actions/deploy-pages', !/npm run build/.test(wf) && 'pages.yml must run npm run build']);

console.log(failures ? `\n${failures} check(s) failed` : '\nAll checks passed');
process.exit(failures ? 1 : 0);
